mapper.update:
UPDATE user_badge
SET progress = progress + #{value},
    updated_at = NOW()
WHERE user_num = #{userNum}
  AND badge_id = #{badgeId}

UPDATE user_badge
SET level = level + 1,
    progress = 0,
    updated_at = NOW()
WHERE user_num = #{userNum}
  AND badge_id = #{badgeId}
  AND level  <  #{maxLevel}

mapper.select:
SELECT requirement_value AS requirementValue
FROM badge_level
WHERE badge_id = #{badgeId}
  AND level = #{level}
